from p"benchmark_harness.jo" import clock
kernel=(values:array<int64> count:int64 offset:int64):>int64=>{
let total:int64=0
loop i in [0..count) total+=values[values.length-1-offset]
return total
}
main=():>void=>{
let values=[loop i in [0..99999) 0] values.push(1) values.push(0)
if kernel(values 1000 1) not=? 1000 panic("warmup")
let started=clock() let checksum=kernel(values 2000000 1) let elapsed=clock()-started
printl"{checksum} {elapsed}"
}

